import { ChangeDetectorRef, Component, EventEmitter, HostListener, Input, Output, SimpleChanges } from '@angular/core';
import { CommonfunctionService } from '../../../core/utility/commonfunction.service';
import { QuickpdfComponent } from '../quickpdf/quickpdf.component';

@Component({
  selector: 'quick-preview',
  standalone: true,
  imports: [QuickpdfComponent],
  templateUrl: './quick-preview.component.html',
  styleUrl: './quick-preview.component.scss'
})
export class QuickPreviewComponent {

  @Input() detail: any;
  @Input() nCaseid: string;
  @Input() fullMode: boolean;
  @Input() isSource: boolean = false;
  @Input() jTexts: string[] = [];
  @Input() isOnSameTab: boolean = false;
  @Output() OnEvent = new EventEmitter<any>();
  onPage: number = 1;
  isLoading: boolean = true;
  path: any;


  @HostListener('window:message', ['$event'])
  onPdf = (event: MessageEvent) => {
    if (event.origin !== window.location.origin) {
      return;
    }

    if (event.data.event == 'ON-INDIVIDUAL') {
      this.previewDoc();
    }


  }

  constructor(private readonly cf: CommonfunctionService, private cdr: ChangeDetectorRef) {

  }

  ngOnInit(): void {
    debugger;
    this.detail;
    if (this.detail?.jOTexts?.length || this.detail.jOT.length) {
      this.jTexts = this.detail.jOTexts || this.detail.jOT || []
    }

    try {
      if (this.detail?.jLinktype?.nPage) {
        this.onPage = this.detail?.jLinktype?.nPage
      } else if (this.detail?.jLinktype?.pages && this.detail?.jLinktype?.pages?.length) {
        this.onPage = this.detail?.jLinktype?.pages[0];
      } else if (this.detail?.jLinktype?.start > 1) {
        this.onPage = this.detail?.jLinktype?.start;
      }
    } catch (error) {
    }

    if (this.detail.nBundledetailid)
      this.path = this.cf.senitizeQuick(this.detail.nBundledetailid, this.onPage, this.nCaseid);
    this.isLoading = false;
    this.cdr.detectChanges();
  }


  ngOnChanges(changes: SimpleChanges): void {
    if (changes['changes'] && !changes['changes'].firstChange) {
    }
  }

  previewDoc() {
    debugger;
    if (!this.detail?.nBundledetailid) return;
    let pg = 1;
    try {
      if (this.detail?.jLinktype?.nPage) {
        pg = this.detail?.jLinktype?.nPage
      } else if (this.detail?.jLinktype?.pages && this.detail?.jLinktype?.pages?.length) {
        pg = this.detail?.jLinktype?.pages[0];
      } else if (this.detail?.jLinktype?.start > 1) {
        pg = this.detail?.jLinktype?.start;
      }
    } catch (error) {
    }
    if (this.isOnSameTab) {
      this.OnEvent.emit({ event: 'OPEN-FILE', data: { ...this.detail, pg: pg } })
    } else {
      this.cf.openHyperLinkFile(this.detail.nBundledetailid, this.nCaseid, null, null, null, pg)
    }

  }

}